package com.wissenup.domain.fee.entity; import jakarta.persistence.*;import lombok.*;import java.time.*;import java.math.*;
@Entity@Table(name="fee_refunds")@Getter@Setter@Builder@NoArgsConstructor@AllArgsConstructor public class FeeRefund{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long refundId;@Column(name="organization_id")private Long organizationId;@Column(name="fee_payment_id")private Long feePaymentId;@Column(name="refund_amount")private BigDecimal refundAmount;private String reason;@Column(name="refunded_at")private LocalDateTime refundedAt;@Column(name="refunded_by")private Long refundedBy;@PrePersist void c(){if(refundedAt==null)refundedAt=LocalDateTime.now();}}
